ui.css:
body:not(.ready) #splay { visibility: hidden; } #views .tang { font-weight: 700; }
/* V1.5 không gian trưng bày khí tài: ghim phía Mỹ / VNCH nền xanh, thẻ thông tin, nút vào đi bộ */
.lbl.hero.btmy b { border-color: #9db8e8; background: rgba(28, 52, 104, .9); color: #eef3ff; cursor: pointer; }
.lbl.hero.ly b { cursor: pointer; }
#btThe { position: fixed; right: 16px; top: 72px; width: min(380px, calc(100vw - 32px)); max-height: calc(100vh - 140px); overflow: auto; z-index: 40; background: rgba(22, 17, 12, .95); color: #f1e8d6; border: 1px solid #c9a24a; border-radius: 12px; padding: 14px 16px; font-size: 13.5px; line-height: 1.45; box-shadow: 0 8px 30px rgba(0,0,0,.5); }
#btThe h3 { margin: 0 28px 4px 0; font-size: 17px; color: #ffe9a8; }
#btThe .ben { font-size: 12px; margin-bottom: 8px; padding: 2px 8px; border-radius: 99px; display: inline-block; }
#btThe .ben.qgp { background: #8e1c14; color: #ffe9a8; } #btThe .ben.my, #btThe .ben.vnch { background: #1c3468; color: #eef3ff; }
#btThe table { width: 100%; border-collapse: collapse; margin: 6px 0; } #btThe td { padding: 4px 6px; border-bottom: 1px solid rgba(255,255,255,.1); vertical-align: top; } #btThe td:first-child { color: #c9b88f; width: 42%; }
#btThe .mh { color: #f0c040; font-size: 12.5px; } #btThe .src { color: #a99d86; font-size: 11.5px; margin-top: 8px; }
#btThe .dong { position: absolute; right: 10px; top: 8px; background: none; border: 0; color: #f1e8d6; font-size: 22px; cursor: pointer; }
#btVao { position: fixed; left: 50%; bottom: 96px; transform: translateX(-50%); z-index: 35; background: #b8862a; color: #1a130b; border: 0; border-radius: 99px; padding: 12px 22px; font-size: 15px; font-weight: 700; cursor: pointer; box-shadow: 0 6px 20px rgba(0,0,0,.45); }
#btVao.nho { left: auto; right: 16px; bottom: auto; top: 128px; transform: none; padding: 8px 14px; font-size: 13px; }
#btVao.cuoi { left: auto; right: 24px; bottom: 104px; transform: none; }
#btVe { position: fixed; left: 24px; bottom: 104px; z-index: 35; background: rgba(28, 22, 15, .92); color: #f1e2b8; border: 1px solid #c9a24a; border-radius: 99px; padding: 12px 20px; font-size: 15px; font-weight: 700; cursor: pointer; box-shadow: 0 6px 20px rgba(0,0,0,.45); }
@media (max-width: 640px) { #btVao.cuoi, #btVe { bottom: 120px; padding: 10px 14px; font-size: 13px; } #btVao.cuoi { right: 10px; } #btVe { left: 10px; } }
/* V1.8: thẻ khí tài ở giữa màn hình; nút quay về trên thẻ tiêu đề */
#btThe { right: auto; top: 50%; left: 50%; transform: translate(-50%, -50%); width: min(460px, calc(100vw - 28px)); max-height: min(78vh, 640px); z-index: 60; box-shadow: 0 0 0 100vmax rgba(0,0,0,.35), 0 12px 40px rgba(0,0,0,.6); }
#btLui { display: inline-grid; place-items: center; width: 24px; height: 24px; margin-right: 8px; border-radius: 50%; border: 1px solid #c9a24a; background: rgba(201,162,74,.15); color: #f1e2b8; font: 700 14px system-ui, sans-serif; cursor: pointer; vertical-align: middle; padding: 0; }
#btLui:hover { background: rgba(201,162,74,.35); }

/* V2.1: thẻ bảng thống kê số liệu (rộng hơn, chia mục) */
#btThe.tk { width: min(640px, calc(100vw - 24px)); max-height: min(84vh, 760px); }
#btThe .phu { color: #c9b88f; font-size: 12.5px; margin-bottom: 6px; }
#btThe h4 { margin: 12px 0 2px; font-size: 14px; color: #f0c040; border-bottom: 1px solid rgba(201,162,74,.45); padding-bottom: 3px; }
#btThe.tk td:first-child { width: 36%; }
#btThe .ng { color: #8f8470; font-size: 11px; white-space: nowrap; }
@media (max-width: 640px) { #btThe.tk { font-size: 12.5px; padding: 12px; } #btThe.tk td { padding: 3px 4px; } }
/* V0.2 (anh Thắng 26/11): nút về Trang chủ thay chữ 'cần đối chiếu tư liệu' ở góc thẻ tên */
#btTrangChu { display: inline-block; margin-top: 7px; font: 700 11px/1 system-ui, sans-serif; padding: 5px 11px; border-radius: 99px; border: 1px solid #c9a24a; background: rgba(201, 162, 74, .2); color: #ffe9a8; cursor: pointer; letter-spacing: .03em; }
#btTrangChu:hover { background: rgba(201, 162, 74, .38); }
